import type { LucideIcon } from "lucide-react";
import Link from "next/link";
import { SERVICES_TEASER } from "@/data/home";

type ServiceCard = { title: string; sub: string; cta: string; href: string; icon: LucideIcon };

export type ServicesTeaserCopy = { eyebrow: string; title: string; subtitle: string };

/** What the section says before the CMS says otherwise. Not in `data/home.ts`
 * because that file is regenerated by `sync-cms` and would lose it. */
const DEFAULT_COPY: ServicesTeaserCopy = {
  eyebrow: "Accompagnement",
  title: "Nos services",
  subtitle: "Nos pharmaciens vous accompagnent, en ligne comme en institut.",
};

export function ServicesTeaser({ cards: cardsProp, copy: copyProp }: { cards?: ServiceCard[]; copy?: ServicesTeaserCopy } = {}) {
  const cards = cardsProp ?? SERVICES_TEASER;
  const copy = copyProp ?? DEFAULT_COPY;
  if (cards.length === 0) return null;

  return (
    <section style={{ maxWidth: "min(1280px,100%)", margin: "0 auto", padding: "var(--sec-pt,var(--sec-y)) var(--sec-pad-x) var(--sec-pb,var(--sec-y))" }}>
      <div style={{ background: "var(--surface-panel)", borderRadius: "clamp(16px,2vw,24px)", padding: "clamp(24px,3.2vw,40px)" }}>
        <div style={{ display: "flex", alignItems: "flex-end", justifyContent: "space-between", marginBottom: 22, gap: 16, flexWrap: "wrap" }}>
          <div>
            <h2 className="sec-title">{copy.title}</h2>
            {copy.subtitle && <div className="sec-deck">{copy.subtitle}</div>}
          </div>
          <Link
            href="/services"
            className="link-hover"
            style={{ flex: "none", whiteSpace: "nowrap", fontSize: 11.5, letterSpacing: ".12em", textTransform: "uppercase", color: "var(--pdh-plum)", borderBottom: "1px solid var(--pdh-plum-divider)", paddingBottom: 3 }}
          >
            Tous nos services
          </Link>
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(min(100%,208px),1fr))", gap: "clamp(12px,1.6vw,18px)" }}>
          {cards.map((c) => (
            <Link
              key={c.title}
              href={c.href}
              className="card-hover"
              style={{
                background: "#fff",
                border: "1px solid var(--pdh-plum-tint)",
                borderRadius: 18,
                padding: 24,
                display: "flex",
                flexDirection: "column",
                gap: 10,
                color: "inherit",
              }}
            >
              <div style={{ width: 44, height: 44, borderRadius: "50%", background: "var(--pdh-plum-tint)", display: "flex", alignItems: "center", justifyContent: "center", color: "var(--pdh-plum)" }}>
                <c.icon aria-hidden="true" size={20} strokeWidth={1.5} />
              </div>
              <div style={{ fontSize: 15, fontWeight: 600 }}>{c.title}</div>
              <div className="sec-deck" style={{ margin: 0 }}>{c.sub}</div>
              <div style={{ fontSize: 11, letterSpacing: ".12em", textTransform: "uppercase", color: "var(--pdh-teal-text)", marginTop: "auto" }}>{c.cta} →</div>
            </Link>
          ))}
        </div>
      </div>
    </section>
  );
}
